// 20 popular Dutch job titles to poll Adzuna for
const KEYWORDS = [
  'software developer', 'administratief medewerker', 'verkoopmedewerker',
  'marketing manager', 'accountant', 'chauffeur', 'verpleegkundige',
  'klantenservice medewerker', 'projectmanager', 'data analist',
  'hr medewerker', 'logistiek medewerker', 'kok', 'grafisch ontwerper',
  'recruiter', 'financieel controller', 'salesmanager',
  'productiemedewerker', 'it beheerder', 'boekhouder'
];
return KEYWORDS.map(keyword => ({ json: { keyword } }));

// Transform Adzuna response → Opstap ingest schema
const BLOCKED_DOMAINS = new Set([
  'werkenbijdefensie.nl', 'defensie.nl', 'werkenvoornederland.nl',
  'politie.nl', 'werkenbijpolitie.nl', 'werkenbijrijksoverheid.nl',
  'rijksoverheid.nl', 'gemeentebanen.nl', 'intermediair.nl'
]);

function contractType(job) {
  const ct = job.contract_type || '';
  const pt = job.contract_time || '';
  if (ct === 'permanent') return 'Vast';
  if (ct === 'contract') return 'Tijdelijk';
  if (pt === 'full_time') return 'Fulltime';
  if (pt === 'part_time') return 'Parttime';
  return '';
}

function salaryRange(job) {
  const lo = job.salary_min, hi = job.salary_max;
  if (lo && hi) return `€${Math.round(lo).toLocaleString('nl-NL')}–€${Math.round(hi).toLocaleString('nl-NL')}/j`;
  if (lo) return `Vanaf €${Math.round(lo).toLocaleString('nl-NL')}/j`;
  return null;
}

const results = $json.results || [];
const now = new Date().toISOString();

const jobs = results
  .filter(job => job.title && job.redirect_url)
  .filter(job => {
    try {
      const domain = new URL(job.redirect_url).hostname.replace(/^www\./, '');
      return !BLOCKED_DOMAINS.has(domain);
    } catch { return true; }
  })
  .map(job => ({
    title: (job.title || '').trim().slice(0, 300),
    company: ((job.company || {}).display_name || 'Onbekend').trim().slice(0, 200),
    location: ((job.location || {}).display_name || 'Nederland').trim().slice(0, 200),
    url: job.redirect_url,
    source: 'adzuna',
    description_snippet: (job.description || '').slice(0, 500),
    salary_range: salaryRange(job),
    salary_min_raw: job.salary_min ? Math.round(job.salary_min) : null,
    salary_max_raw: job.salary_max ? Math.round(job.salary_max) : null,
    contract_type: contractType(job),
    posted_at: job.created ? new Date(job.created).toISOString() : null,
    scraped_at: now
  }));

if (jobs.length === 0) return [];

return [{ json: { jobs, source_keyword: $('Keyword list').item.json.keyword } }];
